def guess_number(n, guess):
    lo, hi = 1, n
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        result = guess(mid)
        if result == 0:
            return mid
        elif result < 0:
            hi = mid - 1                # too high, search lower
        else:
            lo = mid + 1                 # too low, search higher
    return -1

